    storyText1 += "...contaminado.";

    storyText2 = "Un susurro binario, una grieta sin parche.\n";
    storyText2 += "El virus llego disfrazado de ayuda.\n";
    storyText2 += "Un trojano antiguo, mutado. Inteligente.\n";
    storyText2 += "Letal.";

